-- VYPRON SQL schema + row-level security
create table if not exists public.clients (id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade, name text not null, contact text, created_at timestamptz not null default now());
create table if not exists public.agents (id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade, name text not null, contact text, created_at timestamptz not null default now());
create table if not exists public.services (id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade, name text not null, price text, details text, created_at timestamptz not null default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade, title text not null, customer_name text, status text default 'جديد', created_at timestamptz not null default now());
create table if not exists public.subscriptions (id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade, customer_name text not null, plan text, expires_at date, status text default 'نشط', created_at timestamptz not null default now());
alter table public.clients enable row level security; alter table public.agents enable row level security; alter table public.services enable row level security; alter table public.orders enable row level security; alter table public.subscriptions enable row level security;
do $$ declare t text; begin foreach t in array array['clients','agents','services','orders','subscriptions'] loop execute format('drop policy if exists owner_all on public.%I',t); execute format('create policy owner_all on public.%I for all to authenticated using (owner_id = auth.uid()) with check (owner_id = auth.uid())',t); end loop; end $$;
